--
-- Name: prevent_observation_update_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_observation_update_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Observation records are immutable. Insert a corrected observation instead of updating or deleting observation_id=%.', OLD.observation_id;
END;
$$;


--
-- Name: record_consensus_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_consensus_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
      consensus_id,
      version_number,
      statement_text,
      agreement_level,
      summary_of_changes
    ) VALUES (
      NEW.consensus_id,
      NEW.version,
      NEW.consensus_statement,
      NEW.agreement_level,
      'Initial consensus version'
    );
    RETURN NEW;
  END IF;

  IF (
    NEW.version IS DISTINCT FROM OLD.version OR
    NEW.consensus_statement IS DISTINCT FROM OLD.consensus_statement OR
    NEW.agreement_level IS DISTINCT FROM OLD.agreement_level
  ) THEN
      consensus_id,
      version_number,
      statement_text,
      agreement_level,
      summary_of_changes
    ) VALUES (
      NEW.consensus_id,
      NEW.version,
      NEW.consensus_statement,
      NEW.agreement_level,
      'Consensus updated'
    );
  END IF;

  RETURN NEW;
END;
$$;


