--
-- Name: moduleevidencelink; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.moduleevidencelink (
    module_evidence_link_id bigint NOT NULL,
    source_record_id bigint NOT NULL,
    module character varying(32),
    link_role character varying(64) NOT NULL,
    target_kind character varying(32) NOT NULL,
    pathway_id integer,
    entity_id integer,
    edge_id integer,
    local_paper_id integer,
    local_experiment_id integer,
    local_observation_id integer,
    local_claim_id integer,
    support_status character varying(32) DEFAULT 'contextual'::character varying NOT NULL,
    evidence_grade character varying(1),
    context_level character varying(2),
    inference_role character varying(32) DEFAULT 'descriptive'::character varying NOT NULL,
    release_status character varying(32) DEFAULT 'staging'::character varying NOT NULL,
    link_basis text NOT NULL,
    source_field_locator text,
    notes text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT module_evidence_link_basis_nonempty CHECK ((btrim(link_basis) <> ''::text)),
    CONSTRAINT module_evidence_link_context CHECK (((context_level IS NULL) OR ((context_level)::text = ANY ((ARRAY['L0'::character varying, 'L1'::character varying, 'L2'::character varying, 'L3'::character varying, 'L4'::character varying])::text[])))),
    CONSTRAINT module_evidence_link_grade CHECK (((evidence_grade IS NULL) OR ((evidence_grade)::text = ANY ((ARRAY['A'::character varying, 'B'::character varying, 'C'::character varying, 'D'::character varying, 'E'::character varying, 'U'::character varying])::text[])))),
    CONSTRAINT module_evidence_link_included_anchor CHECK ((((release_status)::text <> 'included'::text) OR (local_paper_id IS NOT NULL) OR (local_observation_id IS NOT NULL) OR (local_claim_id IS NOT NULL))),
    CONSTRAINT module_evidence_link_inference_role CHECK (((inference_role)::text = ANY ((ARRAY['descriptive'::character varying, 'predictive'::character varying, 'causal_supporting'::character varying, 'unknown'::character varying])::text[]))),
    CONSTRAINT module_evidence_link_module_name CHECK ((((target_kind)::text <> 'module'::text) OR ((module IS NOT NULL) AND (btrim((module)::text) <> ''::text)))),
    CONSTRAINT module_evidence_link_release_status CHECK (((release_status)::text = ANY ((ARRAY['staging'::character varying, 'included'::character varying, 'held'::character varying, 'screened_out'::character varying, 'retired'::character varying])::text[]))),
    CONSTRAINT module_evidence_link_role CHECK (((link_role)::text = ANY ((ARRAY['member_support'::character varying, 'edge_support'::character varying, 'pathway_state'::character varying, 'spatial_context'::character varying, 'regulatory_context'::character varying, 'contradictory_or_negative'::character varying, 'unresolved'::character varying])::text[]))),
    CONSTRAINT module_evidence_link_status CHECK (((support_status)::text = ANY ((ARRAY['supporting'::character varying, 'contextual'::character varying, 'contradictory'::character varying, 'unresolved'::character varying, 'excluded'::character varying])::text[]))),
    CONSTRAINT module_evidence_link_target_kind CHECK (((target_kind)::text = ANY ((ARRAY['module'::character varying, 'pathway'::character varying, 'pathway_member'::character varying, 'entity'::character varying, 'edge'::character varying])::text[]))),
    CONSTRAINT module_evidence_link_target_shape CHECK (((((target_kind)::text = 'module'::text) AND (pathway_id IS NULL) AND (entity_id IS NULL) AND (edge_id IS NULL)) OR (((target_kind)::text = 'pathway'::text) AND (pathway_id IS NOT NULL) AND (entity_id IS NULL) AND (edge_id IS NULL)) OR (((target_kind)::text = 'pathway_member'::text) AND (pathway_id IS NOT NULL) AND (entity_id IS NOT NULL) AND (edge_id IS NULL)) OR (((target_kind)::text = 'entity'::text) AND (pathway_id IS NULL) AND (entity_id IS NOT NULL) AND (edge_id IS NULL)) OR (((target_kind)::text = 'edge'::text) AND (pathway_id IS NULL) AND (entity_id IS NULL) AND (edge_id IS NOT NULL))))
);


