--
-- Name: signalingphenotype; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.signalingphenotype (
    phenotype_id integer NOT NULL,
    canonical_name character varying(255) NOT NULL,
    phenotype_domain character varying(100),
    ontology_id character varying(100),
    description text,
    notes text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


--
-- Name: signalingphenotype_phenotype_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.signalingphenotype_phenotype_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: signalingphenotype_phenotype_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.signalingphenotype_phenotype_id_seq OWNED BY public.signalingphenotype.phenotype_id;


--
-- Name: v_claim_evidence_chain; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_claim_evidence_chain AS
 SELECT ac.claim_id,
    ac.claim_text,
    ac.claim_type,
    count(DISTINCT el.observation_id) AS supporting_observations,
    string_agg(DISTINCT (el.observation_id)::text, ', '::text) AS observation_ids
   FROM (public.authorclaim ac
     LEFT JOIN public.evidencelink el ON ((ac.claim_id = el.claim_id)))
  GROUP BY ac.claim_id, ac.claim_text, ac.claim_type;


--
-- Name: v_consensus_supporting_papers; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_consensus_supporting_papers AS
 SELECT c.consensus_id,
    c.consensus_statement,
    count(DISTINCT
        CASE
            WHEN ((co.support_type)::text = 'supporting'::text) THEN co.observation_id
            ELSE NULL::integer
        END) AS supporting_obs,
    count(DISTINCT
        CASE
            WHEN ((co.support_type)::text = 'contradicting'::text) THEN co.observation_id
            ELSE NULL::integer
        END) AS contradicting_obs
   FROM (public.consensus c
     LEFT JOIN public.consensus_observation co ON ((c.consensus_id = co.consensus_id)))
  GROUP BY c.consensus_id, c.consensus_statement;


--
-- Name: v_paper_with_experiments; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_paper_with_experiments AS
 SELECT p.paper_id,
    p.title,
    p.publication_year,
    count(DISTINCT e.experiment_id) AS experiment_count,
    count(DISTINCT o.observation_id) AS observation_count
   FROM ((public.paper p
     LEFT JOIN public.experiment e ON ((p.paper_id = e.paper_id)))
     LEFT JOIN public.observation o ON ((e.experiment_id = o.experiment_id)))
  GROUP BY p.paper_id, p.title, p.publication_year;


